import { api } from "@/lib/api";

export const revalidate = 60;

// Mock eval data — replace with real output from run_eval.py
// In production: load from a static JSON file generated by eval/run_eval.py
const MOCK_EVAL_METRICS = {
  timestamp: new Date().toISOString(),
  total_items: 105,
  accuracy: 0.724,
  macro_f1: 0.692,
  weighted_f1: 0.715,
  binary_auc: 0.871,
  per_label: {
    ENTAILED: { precision: 0.812, recall: 0.883, f1: 0.846, support: 60 },
    CONTRADICTED: { precision: 0.778, recall: 0.720, f1: 0.748, support: 25 },
    NOT_ENOUGH_INFO: { precision: 0.533, recall: 0.467, f1: 0.498, support: 20 },
  },
  confusion_matrix: {
    labels: ["ENTAILED", "CONTRADICTED", "NOT_ENOUGH_INFO"],
    matrix: [
      [53, 4, 3],
      [4, 18, 3],
      [4, 7, 9],
    ],
  },
  per_claim_type: {
    SECTION_REF: { total: 65, correct: 48, accuracy: 0.738 },
    CASE_CITATION: { total: 25, correct: 18, accuracy: 0.720 },
    HOLDING: { total: 15, correct: 10, accuracy: 0.667 },
  },
  calibration: {
    mean_confidence_correct: 0.812,
    mean_confidence_incorrect: 0.634,
  },
};

const LABEL_COLORS: Record<string, string> = {
  ENTAILED: "var(--accent-safe)",
  CONTRADICTED: "var(--accent-flagged)",
  NOT_ENOUGH_INFO: "var(--accent-abstain)",
};

const CM_MAX = 60;

function cmOpacity(v: number) {
  return Math.max(0.08, Math.min(0.9, v / CM_MAX));
}

export default async function EvalPage() {
  const m = MOCK_EVAL_METRICS;

  return (
    <>
      <div className="page-header">
        <h1>Evaluation Results</h1>
        <p>
          Gold set · {m.total_items} claims · Run: {new Date(m.timestamp).toLocaleDateString()}
          &nbsp;·&nbsp;
          <a
            href="#"
            style={{ color: "var(--accent-primary)", textDecoration: "none", fontSize: 12 }}
          >
            Run eval harness →
          </a>
        </p>
      </div>

      <div className="error-banner" style={{
        background: "rgba(99,102,241,0.08)",
        border: "1px solid rgba(99,102,241,0.25)",
        color: "#a5b4fc",
        marginBottom: 24
      }}>
        💡 These are illustrative results. Replace with live data by running{" "}
        <code style={{ fontFamily: "monospace", fontSize: 11 }}>
          python eval/run_eval.py --api-url http://localhost:8000/api
        </code>
      </div>

      {/* Top-line metrics */}
      <div className="eval-metrics-grid">
        {[
          { label: "Accuracy", val: `${(m.accuracy * 100).toFixed(1)}%`, color: "var(--text-primary)" },
          { label: "Macro F1", val: m.macro_f1.toFixed(3), color: "var(--accent-primary)" },
          { label: "Weighted F1", val: m.weighted_f1.toFixed(3), color: "var(--accent-primary)" },
          { label: "Binary AUC", val: m.binary_auc?.toFixed(3) ?? "—", color: "var(--accent-safe)" },
          { label: "Total Items", val: String(m.total_items), color: "var(--text-secondary)" },
        ].map(({ label, val, color }) => (
          <div className="metric-cell" key={label}>
            <div className="metric-cell-label">{label}</div>
            <div className="metric-cell-value" style={{ color }}>{val}</div>
          </div>
        ))}
      </div>

      <div className="chart-grid">
        {/* Per-label breakdown */}
        <div className="glass-card">
          <div className="card-title">Per-Label Breakdown</div>
          <div className="card-subtitle">Precision · Recall · F1 by verdict type</div>
          <table className="data-table">
            <thead>
              <tr>
                <th>Label</th>
                <th>Precision</th>
                <th>Recall</th>
                <th>F1</th>
                <th>Support</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(m.per_label).map(([label, vals]) => (
                <tr key={label}>
                  <td>
                    <span style={{ color: LABEL_COLORS[label], fontWeight: 700, fontSize: 12 }}>
                      {label}
                    </span>
                  </td>
                  <td>
                    <div className="trust-bar-wrap">
                      <div className="trust-bar-track">
                        <div
                          className="trust-bar-fill"
                          style={{
                            width: `${vals.precision * 100}%`,
                            background: LABEL_COLORS[label],
                          }}
                        />
                      </div>
                      <span className="trust-val" style={{ color: LABEL_COLORS[label] }}>
                        {vals.precision.toFixed(2)}
                      </span>
                    </div>
                  </td>
                  <td>
                    <div className="trust-bar-wrap">
                      <div className="trust-bar-track">
                        <div
                          className="trust-bar-fill"
                          style={{
                            width: `${vals.recall * 100}%`,
                            background: LABEL_COLORS[label],
                            opacity: 0.7,
                          }}
                        />
                      </div>
                      <span className="trust-val" style={{ color: LABEL_COLORS[label] }}>
                        {vals.recall.toFixed(2)}
                      </span>
                    </div>
                  </td>
                  <td style={{ fontWeight: 700, color: LABEL_COLORS[label] }}>
                    {vals.f1.toFixed(3)}
                  </td>
                  <td style={{ color: "var(--text-muted)" }}>{vals.support}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Confusion matrix */}
        <div className="glass-card">
          <div className="card-title">Confusion Matrix</div>
          <div className="card-subtitle">Predicted (cols) vs Actual (rows)</div>
          <div style={{ overflowX: "auto" }}>
            <table style={{ borderCollapse: "separate", borderSpacing: 4 }}>
              <thead>
                <tr>
                  <th style={{ padding: "4px 8px", color: "var(--text-muted)", fontSize: 10 }}></th>
                  {m.confusion_matrix.labels.map((l) => (
                    <th
                      key={l}
                      style={{
                        padding: "4px 8px",
                        color: LABEL_COLORS[l],
                        fontSize: 9,
                        letterSpacing: "0.5px",
                        textTransform: "uppercase",
                        fontWeight: 700,
                        width: 80,
                        textAlign: "center",
                      }}
                    >
                      {l.split("_")[0]}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {m.confusion_matrix.matrix.map((row, ri) => (
                  <tr key={ri}>
                    <td
                      style={{
                        padding: "4px 8px",
                        color: LABEL_COLORS[m.confusion_matrix.labels[ri]],
                        fontSize: 9,
                        fontWeight: 700,
                        letterSpacing: "0.5px",
                        textTransform: "uppercase",
                      }}
                    >
                      {m.confusion_matrix.labels[ri].split("_")[0]}
                    </td>
                    {row.map((val, ci) => (
                      <td key={ci} style={{ padding: 2 }}>
                        <div
                          className="cm-cell"
                          style={{
                            background:
                              ri === ci
                                ? `rgba(34, 211, 160, ${cmOpacity(val)})`
                                : `rgba(244, 63, 94, ${cmOpacity(val) * 0.6})`,
                            color: val > 10 ? "var(--text-primary)" : "var(--text-secondary)",
                          }}
                        >
                          {val}
                        </div>
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Per claim type + calibration */}
      <div className="chart-grid">
        <div className="glass-card">
          <div className="card-title">Accuracy by Claim Type</div>
          <div className="card-subtitle">Performance breakdown across legal claim categories</div>
          <table className="data-table">
            <thead>
              <tr>
                <th>Claim Type</th>
                <th>Correct / Total</th>
                <th>Accuracy</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(m.per_claim_type).map(([ct, vals]) => (
                <tr key={ct}>
                  <td style={{ fontWeight: 600, color: "var(--text-primary)" }}>{ct}</td>
                  <td style={{ color: "var(--text-muted)" }}>{vals.correct} / {vals.total}</td>
                  <td>
                    <div className="trust-bar-wrap">
                      <div className="trust-bar-track">
                        <div
                          className="trust-bar-fill"
                          style={{
                            width: `${vals.accuracy * 100}%`,
                            background: vals.accuracy >= 0.7
                              ? "var(--accent-safe)"
                              : vals.accuracy >= 0.5
                              ? "var(--accent-abstain)"
                              : "var(--accent-flagged)",
                          }}
                        />
                      </div>
                      <span className="trust-val">{(vals.accuracy * 100).toFixed(0)}%</span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="glass-card">
          <div className="card-title">Confidence Calibration</div>
          <div className="card-subtitle">Are high-confidence predictions more accurate?</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 20, marginTop: 8 }}>
            {[
              {
                label: "Correct Predictions",
                val: m.calibration.mean_confidence_correct,
                color: "var(--accent-safe)",
              },
              {
                label: "Incorrect Predictions",
                val: m.calibration.mean_confidence_incorrect,
                color: "var(--accent-flagged)",
              },
            ].map(({ label, val, color }) => (
              <div key={label}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                  <span style={{ fontSize: 13, color: "var(--text-secondary)" }}>{label}</span>
                  <span style={{ fontSize: 13, fontWeight: 700, color }}>{val.toFixed(3)}</span>
                </div>
                <div className="trust-bar-track" style={{ height: 8 }}>
                  <div
                    className="trust-bar-fill"
                    style={{ width: `${val * 100}%`, background: color }}
                  />
                </div>
              </div>
            ))}
            <div
              style={{
                background: "var(--bg-surface)",
                border: "1px solid var(--bg-border)",
                borderRadius: 8,
                padding: "10px 14px",
                fontSize: 12,
                color: "var(--text-muted)",
              }}
            >
              Gap:{" "}
              <strong style={{ color: "var(--accent-primary)" }}>
                +{(
                  (m.calibration.mean_confidence_correct -
                    m.calibration.mean_confidence_incorrect) *
                  100
                ).toFixed(1)}
                %
              </strong>{" "}
              — model is well-calibrated when this gap is large
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
